let days=[], current=null;
const main=document.querySelector('main'),nav=document.querySelector('#days');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key=(d,t)=>d.id+'/'+t.id, route=(d,t)=>'#'+d.id+(t?'/'+t.id:'');
function readStore(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback;}catch{return fallback;}}
function writeStore(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{toast('Browser storage is full or unavailable. Keep a separate copy of your images.');return false;}}
let completed=readStore('devops-read',[]),fontSize=readStore('devops-font',18);
document.documentElement.style.setProperty('--reading',fontSize+'px');
if(readStore('devops-dark',false))document.body.classList.add('dark');
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3500);}
const wordCount=t=>t.content.split(/\s+/).length;
const minutes=t=>Math.max(1,Math.ceil(wordCount(t)/180));
const summaries=['Understand the information behind every file and request.','Meet the operating system that keeps applications running.','Follow code from a developer’s editor to a running process.','Connect the steps between a change and a working release.','Get comfortable with Linux and your command-line workspace.','Find your way through files, folders, and Linux paths.'];
function sidebar(){nav.innerHTML=days.map(d=>`<a class="day-link ${current?.day.id===d.id?'active':''}" href="${route(d)}"><span>${String(d.number).padStart(2,'0')}</span><div>${esc(d.title)}</div></a>`).join('');}
function getRead(d){return d.topics.filter(t=>completed.includes(key(d,t))).length;}
function dashboard(){current=null;sidebar();document.querySelector('#breadcrumb').textContent='THE LEARNING JOURNEY';const total=days.reduce((n,d)=>n+d.topics.length,0),valid=days.flatMap(d=>d.topics.map(t=>key(d,t)));const read=completed.filter(x=>valid.includes(x)).length;
const next=days.flatMap(d=>d.topics.map(t=>({d,t}))).find(x=>!completed.includes(key(x.d,x.t)))||{d:days[0],t:days[0].topics[0]};
main.innerHTML=`<section class="hero"><div><span class="pill"><span class="live-dot"></span> A LITTLE PROGRESS, EVERY DAY</span><h1>Big ideas.<br>Small steps.<br><em>Your DevOps journey.</em></h1><p>A quiet corner to make sense of the fundamentals. Clear explanations, visual notes, and real-world connections—all in one place.</p><div class="hero-actions"><a class="primary" href="${route(next.d,next.t)}">${read?'Continue reading':'Start the journey'} <span>↗</span></a><a class="secondary" href="#chapters">Explore chapters ↓</a></div></div><img class="hero-art" src="assets/hero.svg" alt="Illustrated workspace with a terminal, connected servers, and a growing learning path"></section><div class="mini-stats"><span><b>${String(days.length).padStart(2,'0')}</b> chapters</span><span><b>${total}</b> lessons to explore</span><span><b>${read}</b> marked as read</span></div><section id="chapters"><div class="section-heading"><div><p class="eyebrow">THE FOUNDATIONS</p><h2>Your next chapter starts here.</h2></div><p>Take your time. Each topic builds<br>on what came before.</p></div><div class="chapter-grid">${days.map(d=>`<article class="chapter"><a href="${route(d)}"><img src="assets/day-${d.number}.svg" alt="${esc(d.title)} visual summary"><div class="chapter-info"><div class="chapter-meta"><span>DAY ${String(d.number).padStart(2,'0')}</span><span>FOUNDATIONS</span></div><h3>${esc(d.title)}</h3><p>${summaries[d.number-1]||'Explore the next step in your learning journey.'}</p><div class="chapter-bottom"><span>${d.topics.length} lessons · ${d.topics.reduce((n,t)=>n+minutes(t),0)} min read</span><span>Explore ↗</span></div><div class="progress-line"><i style="width:${getRead(d)/d.topics.length*100}%"></i></div></div></a></article>`).join('')}</div></section><div class="note-strip"><div><h3>Make these notes your own.</h3><p>Add a diagram or a reference picture inside any lesson. Your reading progress stays in this browser.</p></div><a class="secondary" href="${route(days[0],days[0].topics[0])}">Open a lesson ↗</a></div>`;
}
function dayPage(d){current={day:d};sidebar();document.querySelector('#breadcrumb').textContent=`CHAPTER ${String(d.number).padStart(2,'0')} / OVERVIEW`;main.innerHTML=`<section class="day-hero"><a class="eyebrow" href="#">← ALL CHAPTERS</a><h1>${esc(d.title)}</h1><p>${summaries[d.number-1]||''} · ${d.topics.length} lessons</p><figure class="diagram-block"><img src="assets/day-${d.number}.svg" alt="Visual overview of ${esc(d.title)}"></figure></section><div class="topic-list">${d.topics.map((t,i)=>`<a class="topic-row" href="${route(d,t)}"><span class="num">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(t.title)}</h3><small>${minutes(t)} min read${completed.includes(key(d,t))?' · Read ✓':''}</small></div><span class="arrow">↗</span></a>`).join('')}</div>`;}
function resolveLink(raw,d){
 if(raw.startsWith('https://')||raw.startsWith('http://'))return raw;
 if(raw.startsWith('#'))return raw;
 const parts=(''+d.id+'/'+raw).split('/'), out=[];for(const p of parts){if(p==='..')out.pop();else if(p!=='.')out.push(p);}
 if(out.at(-1)==='README.md')out.pop();
 if(!out.length)return '#';
 const found=days.find(x=>x.id===out[0]);return found?'#'+out.join('/'):'#';
}
function inline(s,d){let v=esc(s);v=v.replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');return v.replace(/\[([^\]]+)\]\(([^)]+)\)/g,(_,label,url)=>{const decoded=url.replace(/&amp;/g,'&');const href=resolveLink(decoded,d);return `<a href="${esc(href)}" ${/^https?:/.test(href)?'target="_blank" rel="noopener noreferrer"':''}>${label}</a>`;});}
function markdown(text,d){const lines=text.replace(/\r/g,'').split('\n');let html='',para=[],list='',code=null,headings=[],h=0;
function flush(){if(para.length){html+='<p>'+inline(para.join(' '),d)+'</p>';para=[];}if(list){html+='</'+list+'>';list='';}}
for(const line of lines){if(line.startsWith('```')){if(code!==null){html+=`<div class="code-wrap"><button class="copy" type="button">Copy</button><pre><code>${esc(code.join('\n'))}</code></pre></div>`;code=null;}else{flush();code=[];}continue;}if(code!==null){code.push(line);continue;}
if(/^# /.test(line))continue;
const heading=line.match(/^(#{2,6})\s+(.+)/);if(heading){flush();const id='section-'+h++;html+=`<h${heading[1].length} id="${id}">${inline(heading[2],d)}</h${heading[1].length}>`;if(heading[1].length===2)headings.push({id,title:heading[2]});continue;}
if(!line.trim()){flush();continue;}
const li=line.match(/^\s*(?:[-*]|\d+\.)\s+(.+)/);if(li){const type=/^\s*\d/.test(line)?'ol':'ul';if(para.length||list&&list!==type)flush();if(!list){list=type;html+='<'+type+'>';}html+='<li>'+inline(li[1],d)+'</li>';continue;}
if(line.startsWith('>')){flush();html+='<blockquote>'+inline(line.replace(/^>\s*/,''),d)+'</blockquote>';continue;}
if(/^---+$/.test(line)){flush();html+='<hr>';continue;}if(list)flush();para.push(line);}
flush();return{html,headings};}
function topicPage(d,t){current={day:d,topic:t};sidebar();document.querySelector('#breadcrumb').textContent=`DAY ${String(d.number).padStart(2,'0')} / ${d.title.toUpperCase()}`;const m=markdown(t.content,d),idx=d.topics.indexOf(t),isRead=completed.includes(key(d,t));main.innerHTML=`<div class="reader-top"><a class="eyebrow" href="${route(d)}">← DAY ${String(d.number).padStart(2,'0')} · ALL LESSONS</a><div class="reader-tools"><button class="small-btn" id="smaller" aria-label="Smaller text">A−</button><button class="small-btn" id="larger" aria-label="Larger text">A+</button><button class="small-btn" id="read-toggle">${isRead?'Read ✓':'Mark as read'}</button></div></div><div class="reader-layout"><article class="article"><p class="eyebrow">LESSON ${String(idx+1).padStart(2,'0')} / ${String(d.topics.length).padStart(2,'0')}</p><h1>${esc(t.title)}</h1><div class="lead-meta">${minutes(t)} min read · ${esc(d.title)}</div><figure class="diagram-block"><img src="assets/day-${d.number}.svg" alt="${esc(d.title)} concept diagram"><figcaption>THE BIG PICTURE · How this lesson fits into Day ${d.number}</figcaption></figure><div class="prose">${m.html}</div><section class="own-images"><h3>Your visual notes</h3><p>Keep a useful diagram, screenshot, or reference image next to this lesson. Images stay in this browser. Keep a separate copy of anything important.</p><label class="upload-label"> <span class="eyebrow">ADD YOUR IMAGE</span><br><input id="image-upload" type="file" accept="image/png,image/jpeg,image/webp" aria-label="Add your reference image"></label><div id="image-gallery"></div><p><a id="youtube" target="_blank" rel="noopener noreferrer">Find a video explanation on YouTube ↗</a><br>Opens a topic search; videos have not been individually reviewed.</p></section><div class="reading-bottom">${idx?`<a class="secondary" href="${route(d,d.topics[idx-1])}">← Previous lesson</a>`:`<a class="secondary" href="${route(d)}">← Chapter overview</a>`}${idx<d.topics.length-1?`<a class="primary" href="${route(d,d.topics[idx+1])}">Next lesson →</a>`:days[days.indexOf(d)+1]?`<a class="primary" href="${route(days[days.indexOf(d)+1])}">Next chapter →</a>`:`<a class="primary" href="#">All chapters ↗</a>`}</div></article><aside class="toc"><p class="eyebrow">ON THIS PAGE</p>${m.headings.map(x=>`<a href="${route(d,t)}?section=${x.id}" data-section="${x.id}">${esc(x.title)}</a>`).join('')}</aside></div>`;
document.querySelector('#youtube').href='https://www.youtube.com/results?search_query='+encodeURIComponent(t.title+' DevOps beginner explanation');
document.querySelector('#smaller').onclick=()=>resize(-1);document.querySelector('#larger').onclick=()=>resize(1);
document.querySelector('#read-toggle').onclick=()=>{const k=key(d,t);const next=completed.includes(k)?completed.filter(x=>x!==k):[...completed,k];if(writeStore('devops-read',next)){completed=next;document.querySelector('#read-toggle').textContent=completed.includes(k)?'Read ✓':'Mark as read';}};
document.querySelectorAll('[data-section]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.section).scrollIntoView({behavior:'smooth',block:'start'});});
document.querySelectorAll('.copy').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.nextElementSibling.textContent);b.textContent='Copied';setTimeout(()=>b.textContent='Copy',1800);}catch{toast('Select and copy the command manually.');}});
showImages();document.querySelector('#image-upload').onchange=upload;
}
function resize(n){fontSize=Math.min(24,Math.max(15,fontSize+n));document.documentElement.style.setProperty('--reading',fontSize+'px');writeStore('devops-font',fontSize);}
function imageKey(){return'devops-images/'+key(current.day,current.topic);}
function showImages(){const box=document.querySelector('#image-gallery'),items=readStore(imageKey(),[]);box.replaceChildren();items.forEach((item,i)=>{const fig=document.createElement('figure'),img=document.createElement('img'),cap=document.createElement('figcaption'),b=document.createElement('button');img.src=item.src;img.alt=item.name;cap.textContent=item.name;b.textContent='Remove image';b.className='small-btn';b.onclick=()=>{const updated=items.filter((_,j)=>j!==i);if(writeStore(imageKey(),updated))showImages();};fig.append(img,cap,b);box.append(fig);});}
function upload(e){const f=e.target.files[0];if(!f)return;if(!/^image\/(png|jpeg|webp)$/.test(f.type)){toast('Choose a PNG, JPEG, or WebP image.');return;}if(f.size>2*1024*1024){toast('Choose an image smaller than 2 MB.');return;}const k=imageKey(),r=new FileReader();r.onload=()=>{const images=readStore(k,[]);images.push({name:f.name,src:r.result});if(writeStore(k,images)&&current?.topic&&imageKey()===k)showImages();};r.onerror=()=>toast('The image could not be read.');r.readAsDataURL(f);e.target.value='';}
function search(q){current=null;sidebar();const needle=q.trim().toLowerCase(),results=days.flatMap(d=>d.topics.filter(t=>(t.title+' '+t.content).toLowerCase().includes(needle)).map(t=>({d,t})));main.innerHTML=`<section class="day-hero"><p class="eyebrow">FIND AN IDEA</p><h1>Search your notes.</h1><p>${results.length} lessons matching “${esc(q)}”</p></section>${results.length?results.map(({d,t})=>`<a class="result" href="${route(d,t)}"><small>DAY ${String(d.number).padStart(2,'0')} · ${esc(d.title)}</small><h3>${esc(t.title)} ↗</h3><small>${minutes(t)} min read</small></a>`).join(''):'<p class="empty">No lessons found. Try “Linux”, “memory”, or “deployment”.</p>'}`;}
function render(){if(!days.length)return;const hash=decodeURIComponent(location.hash.slice(1)).split('?')[0];if(hash==='chapters'){dashboard();requestAnimationFrame(()=>document.querySelector('#chapters').scrollIntoView());return;}const[dId,tId]=hash.split('/'),d=days.find(x=>x.id===dId),t=d?.topics.find(x=>x.id===tId);if(tId&&!t){main.innerHTML='<div class="empty">Lesson not found. <a href="#">Return to all chapters</a>.</div>';return;}t?topicPage(d,t):d?dayPage(d):dashboard();document.querySelector('.sidebar').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');window.scrollTo(0,0);}
document.querySelector('#theme').onclick=()=>{document.body.classList.toggle('dark');writeStore('devops-dark',document.body.classList.contains('dark'));};
document.querySelector('#menu').onclick=()=>{const open=document.querySelector('.sidebar').classList.toggle('open');document.querySelector('#menu').setAttribute('aria-expanded',String(open));};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.sidebar').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');}});
document.querySelector('#search').oninput=e=>{if(e.target.value.trim())search(e.target.value);else render();};
window.addEventListener('hashchange',()=>{document.querySelector('#search').value='';render();});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&e.target.getAttribute('src')?.match(/^assets\/day-/)){e.target.src='assets/hero.svg';e.target.alt='DevOps learning illustration';}},true);
window.loadStudyLessons().then(data=>{days=data;if(!days.length){main.innerHTML='<div class="empty">No lessons are published in the configured source yet.</div>';return;}render();}).catch(error=>{main.innerHTML='<div class="empty"><h2>The notes could not be loaded.</h2><p>'+esc(error.message||'Please try again later.')+'</p><button class="secondary" onclick="location.reload()">Try again</button></div>';});
